//! File Generated by Claude Opus 5.5
//! WebAssembly interface for the browser version: games of 2 to 4 players,
//! any mix of people and bots, with or without the bonus rules, with the
//! dominoes simulated or entered from a real set.
//!
//! The page calls these functions from a Web Worker. Each call writes its
//! reply as JSON, which the page reads from `out_ptr` and `out_len`: the game
//! state for calls that change the game, results for the analysis calls.
//! Squares are given as [rows up from the castle, columns right of the
//! castle, landscape, crowns], landscapes numbered as in `Landscape` with 6
//! for the castle. Dominoes are given by the number on the back of the tile.
use std::sync::Mutex;
use kingdomino_ai::{
    rng,
    core::{ Board, GameState, Landscape, Ruleset, Turn, DOMINOES, game::Rules },
    evaluators::{ evaluator, nn },
    simulation::simulated_deal,
    user_interface::analysis::{ self, ANALYSTS, Stats },
};

/// Bots by the index the page uses
const BOTS: &[&str] = &[
    "mce heuristic",
    "mce race",
    "mce score",
    "mce eoh",
    "claude heuristic",
    "eoh",
    "greedy",
    "nn score",
    "random",
];
const TAKEN: u8 = u8::MAX;
const FULL: u32 = 0x1FFFFFF;
const WEIGHTS: &[u8] = include_bytes!("../../src/evaluators/weights.bin");

/// A game of any size and rules
trait Engine: Send {
    fn state_json(&self) -> String;
    fn play(&mut self, i: usize);
    fn bot_move(&mut self, bot: &str);
    fn choose_set_aside(&mut self);
    fn set_aside(&mut self, domino: u8);
    fn deal(&mut self, domino: u8);
    fn undeal(&mut self);
    fn top_moves(&self, analyst: &str) -> String;
    fn evaluate(&self, i: usize, analyst: &str) -> String;
}

struct Game<const N: usize, const S: usize, R: Ruleset> {
    state: GameState<N, S, R>,
    /// Dominoes are entered from a real set rather than simulated
    entered: bool,
    /// The dominoes dealt this round, which the draw pile forgets once taken
    dealt: [u8; S],
    /// Who took each domino this round, -1 while it is still there
    owners: [i8; S],
    /// Dominoes entered so far for the next draw pile
    pending: Vec<u8>,
    /// Dominoes the game set aside for a real set, to take out of the box
    chosen_aside: Vec<u8>,
    /// Moves for the player to move
    turns: Vec<Turn>,
}

static GAME: Mutex<Option<Box<dyn Engine>>> = Mutex::new(None);
static OUT: Mutex<String> = Mutex::new(String::new());

fn reply(json: String) {
    *OUT.lock().unwrap() = json;
}

/// Runs `f` on the game and replies with the new state
fn change(f: impl FnOnce(&mut dyn Engine)) {
    let mut game = GAME.lock().unwrap();
    let game = game.as_mut().unwrap();
    f(game.as_mut());
    reply(game.state_json());
}

/// Starts a new game. With `entered` the dominoes come from a real set.
#[unsafe(no_mangle)]
pub extern "C" fn new_game(players: u32, middle: bool, harmony: bool, entered: bool, seed_low: u32, seed_high: u32) {
    rng::seed(((seed_high as u64) << 32) | seed_low as u64);
    if !nn::has_weights() { nn::load_weights_from_bytes(WEIGHTS, "weights.bin"); }
    let game: Box<dyn Engine> = match (players, middle, harmony) {
        (2, false, false) => Box::new(Game::<2, 4, Rules<false, false>>::new(entered)),
        (2, true, false) => Box::new(Game::<2, 4, Rules<true, false>>::new(entered)),
        (2, false, true) => Box::new(Game::<2, 4, Rules<false, true>>::new(entered)),
        (2, true, true) => Box::new(Game::<2, 4, Rules<true, true>>::new(entered)),
        (3, false, false) => Box::new(Game::<3, 3, Rules<false, false>>::new(entered)),
        (3, true, false) => Box::new(Game::<3, 3, Rules<true, false>>::new(entered)),
        (3, false, true) => Box::new(Game::<3, 3, Rules<false, true>>::new(entered)),
        (3, true, true) => Box::new(Game::<3, 3, Rules<true, true>>::new(entered)),
        (4, false, false) => Box::new(Game::<4, 4, Rules<false, false>>::new(entered)),
        (4, true, false) => Box::new(Game::<4, 4, Rules<true, false>>::new(entered)),
        (4, false, true) => Box::new(Game::<4, 4, Rules<false, true>>::new(entered)),
        _ => Box::new(Game::<4, 4, Rules<true, true>>::new(entered)),
    };
    *GAME.lock().unwrap() = Some(game);
    change(|_| {});
}

/// Plays move `i` of the moves listed in the state
#[unsafe(no_mangle)]
pub extern "C" fn play(i: u32) {
    change(|g| g.play(i as usize));
}

/// Lets bot `bot`, an index into BOTS, play the move
#[unsafe(no_mangle)]
pub extern "C" fn bot_move(bot: u32) {
    change(|g| g.bot_move(BOTS[bot as usize]));
}

/// Lets the game choose the dominoes set aside from a real set
#[unsafe(no_mangle)]
pub extern "C" fn choose_set_aside() {
    change(|g| g.choose_set_aside());
}

/// Sets aside a domino from a real set, by its index
#[unsafe(no_mangle)]
pub extern "C" fn set_aside(domino: u32) {
    change(|g| g.set_aside(domino as u8));
}

/// Adds a domino from a real set to the draw pile, by its index
#[unsafe(no_mangle)]
pub extern "C" fn deal(domino: u32) {
    change(|g| g.deal(domino as u8));
}

/// Takes back the last domino added to the draw pile
#[unsafe(no_mangle)]
pub extern "C" fn undeal() {
    change(|g| g.undeal());
}

/// The best moves for the player to move as analyst `analyst` sees them
#[unsafe(no_mangle)]
pub extern "C" fn top_moves(analyst: u32) {
    let game = GAME.lock().unwrap();
    reply(game.as_ref().unwrap().top_moves(ANALYSTS[analyst as usize]));
}

/// Results of move `i` as analyst `analyst` sees it
#[unsafe(no_mangle)]
pub extern "C" fn evaluate(i: u32, analyst: u32) {
    let game = GAME.lock().unwrap();
    reply(game.as_ref().unwrap().evaluate(i as usize, ANALYSTS[analyst as usize]));
}

#[unsafe(no_mangle)]
pub extern "C" fn out_ptr() -> *const u8 {
    OUT.lock().unwrap().as_ptr()
}

#[unsafe(no_mangle)]
pub extern "C" fn out_len() -> u32 {
    OUT.lock().unwrap().len() as u32
}

impl<const N: usize, const S: usize, R: Ruleset> Game<N, S, R> {
    fn new(entered: bool) -> Self {
        let mut state = GameState::new(simulated_deal);
        // A real set starts whole, with the dominoes set aside entered later
        if entered { state.deck = (1 << 48) - 1; }
        let mut game = Game {
            state,
            entered,
            dealt: [TAKEN; S],
            owners: [-1; S],
            pending: Vec::new(),
            chosen_aside: Vec::new(),
            turns: Vec::new(),
        };
        game.advance();
        game
    }

    /// Dominoes still to set aside before the game
    fn to_set_aside(&self) -> usize {
        (self.state.deck.count_ones() as usize).saturating_sub(12 * N)
    }

    /// Whether the next draw pile is waiting to be entered
    fn dealing(&self) -> bool {
        self.state.draw_pile == [TAKEN; S] && self.state.deck != 0
    }

    fn over(&self) -> bool {
        self.state.deck == 0 && self.state.draw_pile == [TAKEN; S]
    }

    fn phase(&self) -> &'static str {
        if self.to_set_aside() > 0 { "setaside" }
        else if self.dealing() { "deal" }
        else if self.over() { "over" }
        else { "play" }
    }

    fn start_pile(&mut self, mut pile: [u8; S]) {
        pile.sort_unstable();
        self.state.draw_pile = pile;
        self.dealt = pile;
        self.owners = [-1; S];
    }

    /// Deals a simulated draw pile once every domino is taken, then lists the
    /// moves
    fn advance(&mut self) {
        if !self.entered && self.dealing() {
            let state = &mut self.state;
            let pile = std::array::from_fn(|_| {
                let d = simulated_deal(state.deck);
                state.deck ^= 1 << d;
                d
            });
            self.start_pile(pile);
        }
        self.turns.clear();
        if self.phase() == "play" { self.state.possible_turns_into(&mut self.turns); }
    }

    fn in_deck(&self, domino: u8) -> bool {
        domino < 48 && (self.state.deck >> domino) & 1 == 1
    }
}

impl<const N: usize, const S: usize, R: Ruleset + Send> Engine for Game<N, S, R> {
    fn play(&mut self, i: usize) {
        if i >= self.turns.len() { return; }
        let turn = self.turns[i];
        self.owners[turn.position] = self.state.player_order[0] as i8;
        self.state.play_turn(turn);
        self.advance();
    }

    fn bot_move(&mut self, bot: &str) {
        if self.turns.is_empty() { return; }
        let i = evaluator::<N, S, R>(bot)(&self.state, &self.turns);
        self.play(i);
    }

    fn choose_set_aside(&mut self) {
        while self.to_set_aside() > 0 {
            let d = simulated_deal(self.state.deck);
            self.state.deck ^= 1 << d;
            self.chosen_aside.push(d);
        }
        self.chosen_aside.sort_unstable();
        self.advance();
    }

    fn set_aside(&mut self, domino: u8) {
        if self.to_set_aside() == 0 || !self.in_deck(domino) { return; }
        self.state.deck ^= 1 << domino;
        self.advance();
    }

    fn deal(&mut self, domino: u8) {
        if self.phase() != "deal" || !self.in_deck(domino) { return; }
        self.state.deck ^= 1 << domino;
        self.pending.push(domino);
        if self.pending.len() == S {
            let pile = std::array::from_fn(|i| self.pending[i]);
            self.pending.clear();
            self.start_pile(pile);
        }
        self.advance();
    }

    fn undeal(&mut self) {
        if let Some(d) = self.pending.pop() { self.state.deck |= 1 << d; }
    }

    fn top_moves(&self, analyst: &str) -> String {
        if self.turns.is_empty() { return "[]".into(); }
        let moves = analysis::top_moves(&self.state, &self.turns, analyst);
        let parts: Vec<String> = moves.iter().map(|(i, stats)| self.stats_json(*i, stats)).collect();
        format!("[{}]", parts.join(","))
    }

    fn evaluate(&self, i: usize, analyst: &str) -> String {
        if i >= self.turns.len() { return "null".into(); }
        self.stats_json(i, &analysis::evaluate(&self.state, &self.turns, i, analyst))
    }

    fn state_json(&self) -> String {
        let state = &self.state;
        let active = state.player_order[0] as usize;
        let before = squares(&state.boards[active]);
        let turns = self.turns.iter().map(|t| {
            let new: Vec<_> = squares(&t.board).into_iter()
                .filter(|s| !before.iter().any(|b| b[0] == s[0] && b[1] == s[1]))
                .collect();
            format!("[{},{}]", t.position, squares_json(&new))
        });
        let pile = (0..S).filter(|_| self.dealt[0] != TAKEN).map(|i| format!("[{},{}]", self.dealt[i] + 1, self.owners[i]));
        let rounds = 12 * N / S;
        let dealt = 12 * N - state.deck.count_ones().min(12 * N as u32) as usize;
        let numbers = |ds: &[u8]| list(ds.iter().map(|d| (d + 1).to_string()));
        let deck: Vec<u8> = (0..48).filter(|&d| self.in_deck(d)).collect();
        let fields = [
            ("phase", format!("\"{}\"", self.phase())),
            ("players", N.to_string()),
            ("active", active.to_string()),
            ("order", list(state.player_order.iter().map(|p| p.to_string()))),
            ("round", (dealt / S).max(1).min(rounds).to_string()),
            ("rounds", rounds.to_string()),
            ("set_aside", self.to_set_aside().to_string()),
            ("chosen_aside", numbers(&self.chosen_aside)),
            ("deck", numbers(&deck)),
            ("pending", numbers(&self.pending)),
            ("pile", list(pile)),
            ("scores", list((0..N).map(|p| state.score(p).to_string()))),
            ("bonuses", list(state.boards.iter().map(|b| format!("[{},{}]", R::MIDDLE_KINGDOM && b.middle_kingdom(), R::HARMONY && b.harmony())))),
            ("boards", list(state.boards.iter().map(|b| squares_json(&squares(b))))),
            ("turns", list(turns)),
        ];
        format!("{{{}}}", fields.iter().map(|(k, v)| format!("\"{k}\":{v}")).collect::<Vec<_>>().join(","))
    }
}

impl<const N: usize, const S: usize, R: Ruleset> Game<N, S, R> {
    /// [move, chance of each place, average final score of each player]
    fn stats_json(&self, i: usize, stats: &Stats) -> String {
        let places = list((0..N).map(|k| format!("{:.4}", stats.place(k))));
        let scores = list((0..N).map(|p| format!("{:.2}", stats.score(p))));
        format!("[{i},{places},{scores}]")
    }
}

/// The shape of every domino, by index: [landscape, landscape, crowns]
#[unsafe(no_mangle)]
pub extern "C" fn dominoes() {
    reply(list(DOMINOES.iter().map(|d| format!("[{},{},{}]", d.0 as u8, d.1 as u8, d.2))));
}

fn list(items: impl Iterator<Item = String>) -> String {
    format!("[{}]", items.collect::<Vec<_>>().join(","))
}

/// Every occupied square of a board, relative to the castle
fn squares(board: &Board) -> Vec<[i32; 4]> {
    let castle = (0..6).fold(FULL, |a, l| a & board.landscape(l)).trailing_zeros() as i32;
    (0..25u8).filter_map(|sq| {
        let l = board.square_landscape(sq);
        if l == Landscape::None { return None; }
        let land = if l == Landscape::Castle { 6 } else { l as i32 };
        let (r, c) = (sq as i32 / 5, sq as i32 % 5);
        Some([r - castle / 5, c - castle % 5, land, board.square_crowns(sq) as i32])
    }).collect()
}

fn squares_json(squares: &[[i32; 4]]) -> String {
    list(squares.iter().map(|s| format!("[{},{},{},{}]", s[0], s[1], s[2], s[3])))
}
